Let~$(i_1,\ldots,i_K,i_{K+1})\in\mathcal A_{K+1}$, that is, a fixed active set of size~$K+1$.
\begin{itemize}
\item  If~$(i_1,\ldots,i_K)$ satisfies~(2.10) then
\begin{align*}
&\big\{\widehat \imath_1=i_1,\ldots,\widehat \imath_{k+1}=i_{k+1}\big\}\\
&=\big\{
\lambda_{k+1}^{(i_1,\ldots, i_{k})}=Z_{i_{k+1}}^{(i_1,\cdots, i_{k})}
\leq
Z_{i_k}^{(i_1,\cdots, i_{k-1})}\leq\cdots\leq
Z_{i_2}^{(i_1)}\leq
Z_{i_1}\big\}\\
&
=\big\{
\lambda_{k+1}^{(i_1,\ldots, i_{k})}=Z_{i_{k+1}}^{(i_1,\cdots, i_{k})}
\leq
Z_{i_k}^{(i_1,\cdots, i_{k-1})}\leq\cdots\leq
Z_{i_{a+1}}^{(i_1,\cdots, i_{a})}\leq
Z_{i_{a}}^{(i_1,\cdots, i_{a-1})}=\lambda_{a}^{(i_1,\ldots, i_{a-1})}\big\}\\
&
\quad
\bigcap
\big\{\lambda_{k+1}=Z_{i_{k+1}}^{(i_1,\cdots, i_{k})},\ldots,\lambda_{a}=Z_{i_{a}}^{(i_1,\cdots, i_{a-1})}\big\}


\bigcap
\big\{\widehat \imath_1=i_1,\ldots,\widehat \imath_{a}=i_{a}\big\},
\end{align*}
for any~$0\leq a< k\leq K$ with the convention~$\lambda_0=\infty$.
\item It holds that 
\[
(Z^{(i_1,\ldots, i_{k})}_j)_{ j\neq i_1, \ldots, i_{k}}\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} Z_{i_{k}}^{(i_1,\ldots, i_{k-1})}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} Z_{i_{k-1}}^{(i_1,\ldots, i_{k-2})}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} \cdots 
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} Z_{i_{2}}^{(i_1)}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} Z_{i_1}
\]
are mutually independent, for any~$k\in[K]$. 
\newpage
Furthermore, if $X\beta^0\in H_K$ then
\begin{equation}

{\widehat \sigma^{i_1,\ldots, i_{K}}}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} 
\Big(\frac{Z^{(i_1,\ldots, i_{K})}_j}{\widehat \sigma^{i_1,\ldots, i_{K}}}\Big)_{ j\neq i_1, \ldots, i_{K}}

\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} {Z_{i_{K}}^{(i_1,\ldots, i_{K-1})}}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} \cdots 
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} {Z_{i_{2}}^{(i_1)}}
\protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} {Z_{i_1}}.
\end{equation}
\item  If~$(i_1,\ldots,i_K)$ satisfies~(2.10) then 
\begin{align*}
&\big\{\widehat \imath_1=i_1,\ldots,\widehat \imath_{K}=i_{K}\big\}\\
&=\Big\{
\lambda_{K+1}^{(i_1,\ldots, i_{K})}
\leq
Z_{i_K}^{(i_1,\cdots, i_{K-1})}\leq\cdots\leq
Z_{i_2}^{(i_1)}\leq
Z_{i_1}\Big\}\\
&=\Bigg\{
{\Lambda_{K+1}^{(i_1,\ldots, i_{K})}:=\frac{\lambda_{K+1}^{(i_1,\ldots, i_{K})}}{\widehat \sigma^{i_1,\ldots, i_{K}}}}
\leq
\frac{Z_{i_{K}}^{(i_1,\ldots, i_{K-1})}}{\widehat \sigma^{i_1,\ldots, i_{K}}}
\leq\cdots\leq
\frac{Z_{i_{2}}^{(i_1)}}{\widehat \sigma^{i_1,\ldots, i_{K}}}
\leq
\frac{Z_{i_1}}{\widehat \sigma^{i_1,\ldots, i_{K}}}
\Bigg\}\,.
\end{align*}
\end{itemize}

\begin{equation}

\tag{${\mathcal{A}}_{\mathrm{Irr.}}$}
\forall k\in[K],\ \forall j\notin { T^{k}}:=\{j_1,\ldots, j_k\},\quad X_j^\top X_{T^{k}}\big( X_{T^{k}}^\top  X_{T^{k}}\big)^{-1} s_{k}<1,
\end{equation}

\begin{equation}
\tag{$\bf\mathcal A_{\mathrm{\,Stop}}$}

\mathds 1_{\{\widehat m\leq a\}}\text{~is a measurable function of~}(\lambda_1, \ldots, \lambda_a, \widehat \imath_1,\ldots, \widehat \imath_{K})\,.
\end{equation}
